BEGIN;

ALTER TABLE public.laptops ADD COLUMN IF NOT EXISTS source_type text NOT NULL DEFAULT 'PURCHASE';
ALTER TABLE public.laptops ADD COLUMN IF NOT EXISTS source_reference_id text;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS trade_in_credit_vnd numeric(18,2) NOT NULL DEFAULT 0 CHECK(trade_in_credit_vnd >= 0);

CREATE TABLE public.reservations(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_code text NOT NULL UNIQUE,
 laptop_id bigint NOT NULL REFERENCES laptops(id) ON DELETE RESTRICT, customer_id bigint REFERENCES customers(id) ON DELETE SET NULL,
 order_id bigint REFERENCES orders(id) ON DELETE SET NULL, status text NOT NULL CHECK(status IN('ACTIVE','CONVERTED','EXPIRED','CANCELLED')),
 reserved_by uuid REFERENCES user_profiles(id) ON DELETE SET NULL, reserved_at timestamptz NOT NULL DEFAULT timezone('utc',now()),
 expires_at timestamptz NOT NULL, deposit_payment_id bigint REFERENCES payments(id) ON DELETE SET NULL, notes text NOT NULL DEFAULT '',
 idempotency_key text NOT NULL UNIQUE, converted_at timestamptz, expired_at timestamptz, cancelled_at timestamptz,
 created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT timezone('utc',now()), updated_at timestamptz NOT NULL DEFAULT timezone('utc',now()),
 CHECK(expires_at > reserved_at)
);
CREATE UNIQUE INDEX reservations_one_active_laptop ON reservations(laptop_id) WHERE status='ACTIVE';
CREATE INDEX reservations_status_expiry_idx ON reservations(status,expires_at);

CREATE TABLE public.trade_ins(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trade_in_code text NOT NULL UNIQUE, customer_id bigint REFERENCES customers(id) ON DELETE SET NULL,
 order_id bigint UNIQUE REFERENCES orders(id) ON DELETE SET NULL, brand text NOT NULL, model text NOT NULL, serial text,
 cpu text,gpu text,ram text,ssd text,status text NOT NULL CHECK(status IN('DRAFT','INSPECTING','QUOTED','ACCEPTED','REJECTED','RECEIVED','CONVERTED_TO_INVENTORY','CANCELLED')),
 estimated_value_vnd numeric(18,2),agreed_value_vnd numeric(18,2),reported_condition text,notes text,
 received_at timestamptz,inventory_laptop_id bigint UNIQUE REFERENCES laptops(id) ON DELETE RESTRICT,idempotency_key text NOT NULL UNIQUE,
 created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT timezone('utc',now()),updated_at timestamptz NOT NULL DEFAULT timezone('utc',now()),
 CHECK(agreed_value_vnd IS NULL OR agreed_value_vnd>0)
);
CREATE UNIQUE INDEX trade_ins_serial_active_unique ON trade_ins(lower(serial)) WHERE serial IS NOT NULL AND status NOT IN('REJECTED','CANCELLED');
CREATE UNIQUE INDEX trade_ins_inventory_source_unique ON trade_ins(inventory_laptop_id) WHERE inventory_laptop_id IS NOT NULL;
CREATE TABLE public.trade_in_inspections(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trade_in_id uuid NOT NULL REFERENCES trade_ins(id) ON DELETE RESTRICT,
 status text NOT NULL DEFAULT 'IN_PROGRESS' CHECK(status IN('IN_PROGRESS','COMPLETED')),mainboard_status text NOT NULL DEFAULT 'UNKNOWN' CHECK(mainboard_status IN('ORIGINAL','OFFICIAL_REPLACED','REPAIRED','UNKNOWN')),
 findings text NOT NULL DEFAULT '',inspected_by uuid REFERENCES user_profiles(id),started_at timestamptz NOT NULL DEFAULT timezone('utc',now()),completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT timezone('utc',now())
);
CREATE UNIQUE INDEX trade_in_one_open_inspection ON trade_in_inspections(trade_in_id) WHERE status='IN_PROGRESS';
CREATE TABLE public.trade_in_check_items(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,inspection_id uuid NOT NULL REFERENCES trade_in_inspections(id) ON DELETE RESTRICT,
 check_key text NOT NULL,result text NOT NULL CHECK(result IN('PASS','FAIL','WARNING','NOT_TESTED')),notes text NOT NULL DEFAULT '',UNIQUE(inspection_id,check_key)
);

CREATE TABLE public.commissions(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id bigint NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,laptop_id bigint REFERENCES laptops(id) ON DELETE SET NULL,
 beneficiary_type text NOT NULL CHECK(beneficiary_type IN('EMPLOYEE','CTV','OTHER')),beneficiary_user_id uuid REFERENCES user_profiles(id) ON DELETE SET NULL,beneficiary_name text,
 commission_type text NOT NULL CHECK(commission_type IN('FIXED','MANUAL')),amount_vnd numeric(18,2) NOT NULL CHECK(amount_vnd>0),
 status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','PAID','CANCELLED')),calculation_basis text NOT NULL,
 calculation_snapshot_json jsonb,earned_at timestamptz NOT NULL,approved_at timestamptz,paid_at timestamptz,payment_account_id uuid REFERENCES cash_accounts(id),payment_reference text,
 idempotency_key text NOT NULL UNIQUE,notes text NOT NULL DEFAULT '',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT timezone('utc',now()),updated_at timestamptz NOT NULL DEFAULT timezone('utc',now()),
 CHECK(beneficiary_user_id IS NOT NULL OR btrim(coalesce(beneficiary_name,''))<>'')
);
CREATE UNIQUE INDEX commissions_source_unique ON commissions(order_id,beneficiary_type,coalesce(beneficiary_user_id::text,beneficiary_name),commission_type) WHERE status<>'CANCELLED';

CREATE OR REPLACE FUNCTION public.next_salesops_code(p_prefix text,p_table regclass,p_column text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE day text:=to_char(current_date,'YYYYMMDD');seq integer;result text;
BEGIN PERFORM pg_advisory_xact_lock(hashtext(p_prefix||day));EXECUTE format('SELECT coalesce(max((regexp_match(%I,$1))[1]::int),0)+1 FROM %s WHERE %I LIKE $2',p_column,p_table,p_column) INTO seq USING '(\d+)$',p_prefix||'-'||day||'-%';result:=p_prefix||'-'||day||'-'||lpad(seq::text,3,'0');RETURN result;END $$;

CREATE OR REPLACE FUNCTION public.create_trade_in(p_data jsonb,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t trade_ins%ROWTYPE;
BEGIN SELECT * INTO t FROM trade_ins WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(t);END IF;IF length(btrim(coalesce(p_data->>'brand',''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p_data->>'model',''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Hãng và model là bắt buộc';END IF;INSERT INTO trade_ins(trade_in_code,customer_id,order_id,brand,model,serial,cpu,gpu,ram,ssd,status,reported_condition,notes,idempotency_key,created_by) VALUES(next_salesops_code('TI','trade_ins','trade_in_code'),nullif(p_data->>'customer_id','')::bigint,nullif(p_data->>'order_id','')::bigint,btrim(p_data->>'brand'),btrim(p_data->>'model'),nullif(btrim(coalesce(p_data->>'serial','')),''),nullif(p_data->>'cpu',''),nullif(p_data->>'gpu',''),nullif(p_data->>'ram',''),nullif(p_data->>'ssd',''),'DRAFT',left(coalesce(p_data->>'reported_condition',''),2000),left(coalesce(p_data->>'notes',''),2000),p_idempotency_key,p_actor) RETURNING * INTO t;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN',t.id::text,'CREATE',jsonb_build_object('event','TRADE_IN_CREATED','code',t.trade_in_code),p_actor);RETURN to_jsonb(t);EXCEPTION WHEN unique_violation THEN SELECT * INTO t FROM trade_ins WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(t);END IF;RAISE;END $$;

CREATE OR REPLACE FUNCTION public.start_trade_in_inspection(p_id uuid,p_user_id uuid,p_mainboard_status text,p_findings text,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t trade_ins%ROWTYPE;i trade_in_inspections%ROWTYPE;
BEGIN SELECT * INTO i FROM trade_in_inspections WHERE trade_in_id=p_id AND status='IN_PROGRESS';IF FOUND THEN RETURN to_jsonb(i);END IF;SELECT * INTO t FROM trade_ins WHERE id=p_id FOR UPDATE;IF NOT FOUND OR t.status NOT IN('DRAFT','INSPECTING') THEN RAISE EXCEPTION 'Trade-in không thể bắt đầu inspection';END IF;INSERT INTO trade_in_inspections(trade_in_id,mainboard_status,findings,inspected_by) VALUES(t.id,p_mainboard_status,left(coalesce(p_findings,''),5000),p_user_id) RETURNING * INTO i;UPDATE trade_ins SET status='INSPECTING',updated_at=timezone('utc',now()) WHERE id=t.id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN_INSPECTION',i.id::text,'CREATE',jsonb_build_object('event','TRADE_IN_INSPECTION_STARTED','trade_in_id',t.id,'idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(i);END $$;

CREATE OR REPLACE FUNCTION public.complete_trade_in_inspection(p_id uuid,p_mainboard_status text,p_findings text,p_checks jsonb,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE i trade_in_inspections%ROWTYPE;entry jsonb;
BEGIN SELECT * INTO i FROM trade_in_inspections WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy inspection';END IF;IF i.status='COMPLETED' THEN RETURN to_jsonb(i);END IF;IF p_mainboard_status NOT IN('ORIGINAL','OFFICIAL_REPLACED','REPAIRED','UNKNOWN') OR jsonb_typeof(coalesce(p_checks,'[]'::jsonb))<>'array' THEN RAISE EXCEPTION 'Kết quả inspection không hợp lệ';END IF;FOR entry IN SELECT value FROM jsonb_array_elements(p_checks) LOOP IF entry->>'result' NOT IN('PASS','FAIL','WARNING','NOT_TESTED') OR btrim(coalesce(entry->>'check_key',''))='' THEN RAISE EXCEPTION 'Checklist không hợp lệ';END IF;INSERT INTO trade_in_check_items(inspection_id,check_key,result,notes) VALUES(i.id,upper(left(entry->>'check_key',60)),entry->>'result',left(coalesce(entry->>'notes',''),1000));END LOOP;UPDATE trade_in_inspections SET status='COMPLETED',mainboard_status=p_mainboard_status,findings=left(coalesce(p_findings,''),5000),completed_at=timezone('utc',now()) WHERE id=i.id RETURNING * INTO i;UPDATE trade_ins SET status='QUOTED',updated_at=timezone('utc',now()) WHERE id=i.trade_in_id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN_INSPECTION',i.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_INSPECTION_COMPLETED','idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(i);END $$;

CREATE OR REPLACE FUNCTION public.reject_trade_in(p_id uuid,p_reason text,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t trade_ins%ROWTYPE;BEGIN UPDATE trade_ins SET status='REJECTED',notes=left(concat_ws(E'\n',notes,'Từ chối: '||btrim(p_reason)),2000),updated_at=timezone('utc',now()) WHERE id=p_id AND status IN('DRAFT','INSPECTING','QUOTED') RETURNING * INTO t;IF NOT FOUND THEN RAISE EXCEPTION 'Trade-in không thể từ chối';END IF;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN',t.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_REJECTED','reason',left(p_reason,500)),p_actor);RETURN to_jsonb(t);END $$;

CREATE OR REPLACE FUNCTION public.receive_trade_in(p_id uuid,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t trade_ins%ROWTYPE;BEGIN SELECT * INTO t FROM trade_ins WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy trade-in';END IF;IF t.status IN('RECEIVED','CONVERTED_TO_INVENTORY') THEN RETURN to_jsonb(t);END IF;IF t.status<>'ACCEPTED' THEN RAISE EXCEPTION 'Chỉ trade-in ACCEPTED được nhận';END IF;UPDATE trade_ins SET status='RECEIVED',received_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE id=t.id RETURNING * INTO t;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN',t.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_RECEIVED','idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(t);END $$;

CREATE OR REPLACE FUNCTION public.expire_reservations(p_actor text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE n integer;
BEGIN UPDATE reservations SET status='EXPIRED',expired_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE status='ACTIVE' AND expires_at<=timezone('utc',now());GET DIAGNOSTICS n=ROW_COUNT;IF n>0 THEN INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) SELECT 'RESERVATION',id::text,'UPDATE',jsonb_build_object('event','RESERVATION_EXPIRED'),p_actor FROM reservations WHERE expired_at>=transaction_timestamp();END IF;RETURN n;END $$;

CREATE OR REPLACE FUNCTION public.create_reservation(p_laptop_id bigint,p_customer_id bigint,p_order_id bigint,p_expires_at timestamptz,p_deposit_payment_id bigint,p_notes text,p_user_id uuid,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r reservations%ROWTYPE;l laptops%ROWTYPE;
BEGIN SELECT * INTO r FROM reservations WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(r);END IF;PERFORM expire_reservations(p_actor);SELECT * INTO l FROM laptops WHERE id=p_laptop_id FOR UPDATE;IF NOT FOUND OR lower(l.status)<>'available' OR NOT l.is_active OR l.is_locked THEN RAISE EXCEPTION 'Laptop không đủ điều kiện giữ máy';END IF;IF p_expires_at<=timezone('utc',now()) THEN RAISE EXCEPTION 'Thời hạn giữ máy không hợp lệ';END IF;INSERT INTO reservations(reservation_code,laptop_id,customer_id,order_id,status,reserved_by,expires_at,deposit_payment_id,notes,idempotency_key,created_by) VALUES(next_salesops_code('RSV','reservations','reservation_code'),l.id,p_customer_id,p_order_id,'ACTIVE',p_user_id,p_expires_at,p_deposit_payment_id,left(coalesce(p_notes,''),2000),p_idempotency_key,p_actor) RETURNING * INTO r;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'CREATE',jsonb_build_object('event','RESERVATION_CREATED','laptop_id',l.id),p_actor);RETURN to_jsonb(r);EXCEPTION WHEN unique_violation THEN SELECT * INTO r FROM reservations WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(r);END IF;RAISE EXCEPTION 'Laptop đã có reservation đang hoạt động';END $$;

CREATE OR REPLACE FUNCTION public.cancel_reservation(p_id uuid,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r reservations%ROWTYPE;
BEGIN SELECT * INTO r FROM reservations WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy reservation';END IF;IF r.status='CANCELLED' THEN RETURN to_jsonb(r);END IF;IF r.status<>'ACTIVE' THEN RAISE EXCEPTION 'Chỉ reservation ACTIVE được hủy';END IF;UPDATE reservations SET status='CANCELLED',cancelled_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE id=r.id RETURNING * INTO r;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'UPDATE',jsonb_build_object('event','RESERVATION_CANCELLED','deposit_held',r.deposit_payment_id IS NOT NULL,'idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(r);END $$;

CREATE OR REPLACE FUNCTION public.extend_reservation(p_id uuid,p_expires_at timestamptz,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r reservations%ROWTYPE;
BEGIN SELECT * INTO r FROM reservations WHERE id=p_id FOR UPDATE;IF NOT FOUND OR r.status<>'ACTIVE' OR r.expires_at<=timezone('utc',now()) OR p_expires_at<=r.expires_at THEN RAISE EXCEPTION 'Không thể gia hạn reservation';END IF;UPDATE reservations SET expires_at=p_expires_at,updated_at=timezone('utc',now()) WHERE id=r.id RETURNING * INTO r;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'UPDATE',jsonb_build_object('event','RESERVATION_EXTENDED','expires_at',p_expires_at,'idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(r);END $$;

CREATE OR REPLACE FUNCTION public.convert_reservation_to_order(p_id uuid,p_order_id bigint,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r reservations%ROWTYPE;o orders%ROWTYPE;l laptops%ROWTYPE;
BEGIN SELECT * INTO r FROM reservations WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy reservation';END IF;IF r.status='CONVERTED' THEN RETURN to_jsonb(r);END IF;SELECT * INTO l FROM laptops WHERE id=r.laptop_id FOR UPDATE;IF r.status<>'ACTIVE' OR r.expires_at<=timezone('utc',now()) THEN RAISE EXCEPTION 'Reservation không còn hiệu lực';END IF;SELECT * INTO o FROM orders WHERE id=coalesce(p_order_id,r.order_id) FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Cần order hợp lệ để chuyển đổi';END IF;IF o.laptop_id IS NOT NULL AND o.laptop_id<>r.laptop_id THEN RAISE EXCEPTION 'Order đã gắn laptop khác';END IF;UPDATE orders SET laptop_id=r.laptop_id,requested_laptop_id=r.laptop_id,reservation_expires_at=r.expires_at,updated_at=timezone('utc',now()) WHERE id=o.id;UPDATE reservations SET status='CONVERTED',order_id=o.id,converted_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE id=r.id RETURNING * INTO r;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'UPDATE',jsonb_build_object('event','RESERVATION_CONVERTED','order_id',o.id,'idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(r);END $$;

CREATE OR REPLACE FUNCTION public.accept_trade_in(p_id uuid,p_order_id bigint,p_estimated numeric,p_agreed numeric,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t trade_ins%ROWTYPE;o orders%ROWTYPE;
BEGIN IF p_agreed<=0 THEN RAISE EXCEPTION 'Giá trị thỏa thuận phải lớn hơn 0';END IF;SELECT * INTO t FROM trade_ins WHERE id=p_id FOR UPDATE;IF NOT FOUND OR t.status NOT IN('QUOTED','INSPECTING') THEN RAISE EXCEPTION 'Trade-in chưa sẵn sàng chấp nhận';END IF;SELECT * INTO o FROM orders WHERE id=p_order_id FOR UPDATE;IF NOT FOUND OR o.order_status IN('cancelled','returned') THEN RAISE EXCEPTION 'Order không hợp lệ';END IF;IF o.debt_amount*1000000<p_agreed THEN RAISE EXCEPTION 'Trade-in credit vượt nghĩa vụ khách hàng';END IF;UPDATE orders SET trade_in_credit_vnd=trade_in_credit_vnd+p_agreed,debt_amount=debt_amount-p_agreed/1000000,trade_in_laptop_id=NULL,updated_at=timezone('utc',now()) WHERE id=o.id;UPDATE trade_ins SET status='ACCEPTED',order_id=o.id,estimated_value_vnd=p_estimated,agreed_value_vnd=p_agreed,updated_at=timezone('utc',now()) WHERE id=t.id RETURNING * INTO t;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN',t.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_ACCEPTED','order_id',o.id,'credit_vnd',p_agreed),p_actor);RETURN to_jsonb(t);END $$;

CREATE OR REPLACE FUNCTION public.convert_trade_in_to_inventory(p_id uuid,p_data jsonb,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t trade_ins%ROWTYPE;l laptops%ROWTYPE;
BEGIN SELECT * INTO t FROM trade_ins WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy trade-in';END IF;IF t.inventory_laptop_id IS NOT NULL THEN SELECT * INTO l FROM laptops WHERE id=t.inventory_laptop_id;RETURN to_jsonb(l);END IF;IF t.status<>'RECEIVED' OR t.agreed_value_vnd<=0 THEN RAISE EXCEPTION 'Trade-in chưa được nhận hợp lệ';END IF;INSERT INTO laptops(serial,name,category,status,location,import_price_vnd,is_locked,is_active,source_type,source_reference_id,created_at) VALUES(coalesce(nullif(t.serial,''),'TI-'||left(t.id::text,8)),t.brand||' '||t.model,coalesce(p_data->>'category','TRADE_IN'),'waiting_qc',coalesce(p_data->>'location','BAC_NINH'),t.agreed_value_vnd/1000000,true,true,'TRADE_IN',t.id::text,timezone('utc',now())) RETURNING * INTO l;INSERT INTO laptop_cost_components(laptop_id,cost_type,amount_vnd,source_type,source_id,description,created_by) VALUES(l.id,'TRADE_IN_ACQUISITION',t.agreed_value_vnd,'TRADE_IN',t.id::text,'Thu cũ đổi mới '||t.trade_in_code,p_actor);INSERT INTO stock_movements(laptop_id,movement_type,to_location,note,performed_by) VALUES(l.id,'TRADE_IN_RECEIVE',l.location,'Trade-in '||t.trade_in_code,p_actor);UPDATE trade_ins SET status='CONVERTED_TO_INVENTORY',inventory_laptop_id=l.id,updated_at=timezone('utc',now()) WHERE id=t.id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN',t.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_CONVERTED','laptop_id',l.id,'idempotency_key',p_idempotency_key),p_actor);RETURN to_jsonb(l);END $$;

CREATE OR REPLACE FUNCTION public.generate_commission(p_order_id bigint,p_data jsonb,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE o orders%ROWTYPE;c commissions%ROWTYPE;
BEGIN SELECT * INTO c FROM commissions WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(c);END IF;SELECT * INTO o FROM orders WHERE id=p_order_id FOR UPDATE;IF NOT FOUND OR o.order_status NOT IN('prepared','shipping','done') OR o.cost_snapshotted_at IS NULL THEN RAISE EXCEPTION 'Commission chỉ tạo cho sale đã committed và có snapshot';END IF;INSERT INTO commissions(order_id,laptop_id,beneficiary_type,beneficiary_user_id,beneficiary_name,commission_type,amount_vnd,status,calculation_basis,calculation_snapshot_json,earned_at,idempotency_key,notes,created_by) VALUES(o.id,o.laptop_id,p_data->>'beneficiary_type',nullif(p_data->>'beneficiary_user_id','')::uuid,p_data->>'beneficiary_name',coalesce(p_data->>'commission_type','FIXED'),(p_data->>'amount_vnd')::numeric,'PENDING','ORDER_COST_SNAPSHOT',jsonb_build_object('sale_price_vnd',o.sale_price*1000000,'gross_profit_snapshot_vnd',o.gross_profit_snapshot_vnd,'net_contribution_before_commission_vnd',o.net_contribution_snapshot_vnd),timezone('utc',now()),p_idempotency_key,left(coalesce(p_data->>'notes',''),2000),p_actor) RETURNING * INTO c;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COMMISSION',c.id::text,'CREATE',jsonb_build_object('event','COMMISSION_CREATED','order_id',o.id,'amount_vnd',c.amount_vnd),p_actor);RETURN to_jsonb(c);END $$;

CREATE OR REPLACE FUNCTION public.approve_commission(p_id uuid,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE c commissions%ROWTYPE;BEGIN UPDATE commissions SET status='APPROVED',approved_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE id=p_id AND status='PENDING' RETURNING * INTO c;IF NOT FOUND THEN RAISE EXCEPTION 'Commission không ở trạng thái PENDING';END IF;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COMMISSION',c.id::text,'UPDATE',jsonb_build_object('event','COMMISSION_APPROVED'),p_actor);RETURN to_jsonb(c);END $$;
CREATE OR REPLACE FUNCTION public.pay_commission(p_id uuid,p_account_id uuid,p_reference text,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE c commissions%ROWTYPE;a cash_accounts%ROWTYPE;tx account_transactions%ROWTYPE;BEGIN SELECT * INTO c FROM commissions WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy commission';END IF;IF c.status='PAID' THEN RETURN to_jsonb(c);END IF;IF c.status<>'APPROVED' THEN RAISE EXCEPTION 'Commission chưa được duyệt';END IF;a:=assert_cash_account(p_account_id,'VND',timezone('utc',now()));INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by) VALUES(a.id,'OUT',c.amount_vnd,'VND','COMMISSION',c.id::text,'COMMISSION_PAYMENT',timezone('utc',now()),'Chi hoa hồng order #'||c.order_id,p_idempotency_key||'-CASH',p_actor) RETURNING * INTO tx;UPDATE commissions SET status='PAID',paid_at=timezone('utc',now()),payment_account_id=a.id,payment_reference=left(coalesce(p_reference,''),300),updated_at=timezone('utc',now()) WHERE id=c.id RETURNING * INTO c;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COMMISSION',c.id::text,'UPDATE',jsonb_build_object('event','COMMISSION_PAID','account_id',a.id),p_actor);RETURN to_jsonb(c);END $$;

CREATE OR REPLACE FUNCTION public.guard_commission_history() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN IF OLD.status IN('APPROVED','PAID') AND (NEW.amount_vnd IS DISTINCT FROM OLD.amount_vnd OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.beneficiary_type IS DISTINCT FROM OLD.beneficiary_type OR NEW.beneficiary_user_id IS DISTINCT FROM OLD.beneficiary_user_id OR NEW.beneficiary_name IS DISTINCT FROM OLD.beneficiary_name OR NEW.calculation_basis IS DISTINCT FROM OLD.calculation_basis OR NEW.calculation_snapshot_json IS DISTINCT FROM OLD.calculation_snapshot_json) THEN RAISE EXCEPTION 'Commission đã duyệt là bất biến';END IF;IF OLD.status='PAID' AND NEW.status<>'PAID' THEN RAISE EXCEPTION 'Commission đã chi không thể đổi trạng thái';END IF;RETURN NEW;END $$;
CREATE TRIGGER commissions_immutable BEFORE UPDATE ON commissions FOR EACH ROW EXECUTE FUNCTION guard_commission_history();

CREATE OR REPLACE FUNCTION public.cancel_pending_commissions_for_order() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN IF NEW.order_status IN('cancelled','returned') AND OLD.order_status IS DISTINCT FROM NEW.order_status THEN UPDATE commissions SET status='CANCELLED',updated_at=timezone('utc',now()),notes=left(concat_ws(E'\n',notes,'Tự động hủy do order '||NEW.order_status),2000) WHERE order_id=NEW.id AND status='PENDING';END IF;RETURN NEW;END $$;
CREATE TRIGGER orders_cancel_pending_commissions AFTER UPDATE OF order_status ON orders FOR EACH ROW EXECUTE FUNCTION cancel_pending_commissions_for_order();

ALTER TABLE account_transactions DROP CONSTRAINT IF EXISTS account_transactions_reference_type_check;
ALTER TABLE account_transactions ADD CONSTRAINT account_transactions_reference_type_check CHECK(reference_type IN('PAYMENT','SUPPLIER_PAYMENT','SUPPLIER_REFUND','COD_SETTLEMENT','COMMISSION','MANUAL','TRANSFER'));
ALTER TABLE account_transactions DROP CONSTRAINT IF EXISTS account_transactions_transaction_type_check;
ALTER TABLE account_transactions ADD CONSTRAINT account_transactions_transaction_type_check CHECK(transaction_type IN('CUSTOMER_PAYMENT','COD_SETTLEMENT','SUPPLIER_PAYMENT','SUPPLIER_REFUND','COMMISSION_PAYMENT','MANUAL_IN','MANUAL_OUT','TRANSFER_IN','TRANSFER_OUT','OTHER'));

ALTER TABLE laptop_cost_components DROP CONSTRAINT IF EXISTS laptop_cost_components_cost_type_check;
ALTER TABLE laptop_cost_components ADD CONSTRAINT laptop_cost_components_cost_type_check CHECK(cost_type IN('PURCHASE','TRADE_IN_ACQUISITION','CN_SHIPPING','VN_SHIPPING','PAYMENT_FEE','REPAIR','RAM_UPGRADE','SSD_UPGRADE','ACCESSORY','CLEANING','OTHER','REFUND_CREDIT'));
ALTER TABLE laptop_cost_components DROP CONSTRAINT IF EXISTS laptop_cost_components_source_type_check;
ALTER TABLE laptop_cost_components ADD CONSTRAINT laptop_cost_components_source_type_check CHECK(source_type IN('PURCHASE_ITEM','TRADE_IN','REPAIR_JOB','COST_ALLOCATION','MANUAL','SUPPLIER_REFUND'));

CREATE OR REPLACE VIEW public.laptop_landed_costs AS
WITH sums AS (
 SELECT laptop_id,
  sum(amount_vnd) FILTER(WHERE cost_type IN('PURCHASE','TRADE_IN_ACQUISITION')) purchase_cost_vnd,
  sum(amount_vnd) FILTER(WHERE cost_type='CN_SHIPPING') cn_shipping_vnd,
  sum(amount_vnd) FILTER(WHERE cost_type='VN_SHIPPING') vn_shipping_vnd,
  sum(amount_vnd) FILTER(WHERE cost_type='REPAIR') repair_cost_vnd,
  sum(amount_vnd) FILTER(WHERE cost_type IN('RAM_UPGRADE','SSD_UPGRADE')) upgrade_cost_vnd,
  sum(amount_vnd) FILTER(WHERE cost_type='ACCESSORY') accessory_cost_vnd,
  sum(amount_vnd) FILTER(WHERE cost_type IN('CLEANING','OTHER','PAYMENT_FEE')) other_cost_vnd,
  sum(amount_vnd) FILTER(WHERE cost_type='REFUND_CREDIT') refund_credit_vnd
 FROM laptop_cost_components WHERE voided_at IS NULL GROUP BY laptop_id
), completeness AS (
 SELECT l.id,
  CASE WHEN l.source_type='TRADE_IN' AND EXISTS(SELECT 1 FROM laptop_cost_components c WHERE c.laptop_id=l.id AND c.source_type='TRADE_IN' AND c.cost_type='TRADE_IN_ACQUISITION' AND c.voided_at IS NULL) THEN CASE WHEN EXISTS(SELECT 1 FROM repair_jobs r WHERE r.laptop_id=l.id AND r.status NOT IN('COMPLETED','CANCELLED')) THEN 'INCOMPLETE' ELSE 'COMPLETE' END WHEN l.purchase_item_id IS NULL THEN 'LEGACY' WHEN pb.exchange_rate IS NULL OR pb.exchange_rate<=0 THEN 'INCOMPLETE' WHEN EXISTS(SELECT 1 FROM repair_jobs r WHERE r.laptop_id=l.id AND r.status NOT IN('COMPLETED','CANCELLED')) THEN 'INCOMPLETE' ELSE 'COMPLETE' END cost_status,
  array_remove(ARRAY[CASE WHEN l.source_type<>'TRADE_IN' AND l.purchase_item_id IS NULL THEN 'LEGACY_NO_PURCHASE_LINEAGE' END,CASE WHEN l.source_type='TRADE_IN' AND NOT EXISTS(SELECT 1 FROM laptop_cost_components c WHERE c.laptop_id=l.id AND c.source_type='TRADE_IN' AND c.cost_type='TRADE_IN_ACQUISITION' AND c.voided_at IS NULL) THEN 'MISSING_TRADE_IN_ACQUISITION' END,CASE WHEN EXISTS(SELECT 1 FROM repair_jobs r WHERE r.laptop_id=l.id AND r.status NOT IN('COMPLETED','CANCELLED')) THEN 'ACTIVE_REPAIR_COST_PENDING' END],NULL) reasons
 FROM laptops l LEFT JOIN purchase_items pi ON pi.id=l.purchase_item_id LEFT JOIN purchase_batches pb ON pb.id=pi.purchase_batch_id
)
SELECT l.id laptop_id,coalesce(s.purchase_cost_vnd,0)::numeric(18,2) purchase_cost_vnd,coalesce(s.cn_shipping_vnd,0)::numeric(18,2) cn_shipping_vnd,coalesce(s.vn_shipping_vnd,0)::numeric(18,2) vn_shipping_vnd,coalesce(s.repair_cost_vnd,0)::numeric(18,2) repair_cost_vnd,coalesce(s.upgrade_cost_vnd,0)::numeric(18,2) upgrade_cost_vnd,coalesce(s.accessory_cost_vnd,0)::numeric(18,2) accessory_cost_vnd,coalesce(s.other_cost_vnd,0)::numeric(18,2) other_cost_vnd,coalesce(s.refund_credit_vnd,0)::numeric(18,2) refund_credit_vnd,greatest(coalesce(s.purchase_cost_vnd,0)+coalesce(s.cn_shipping_vnd,0)+coalesce(s.vn_shipping_vnd,0)+coalesce(s.repair_cost_vnd,0)+coalesce(s.upgrade_cost_vnd,0)+coalesce(s.accessory_cost_vnd,0)+coalesce(s.other_cost_vnd,0)-coalesce(s.refund_credit_vnd,0),0)::numeric(18,2) landed_cost_vnd,c.cost_status,c.reasons
FROM laptops l LEFT JOIN sums s ON s.laptop_id=l.id JOIN completeness c ON c.id=l.id;

CREATE OR REPLACE VIEW public.order_sales_operations_summary AS SELECT o.id order_id,o.sale_price*1000000 sale_revenue_vnd,o.trade_in_credit_vnd,o.debt_amount*1000000 customer_outstanding_vnd,o.gross_profit_snapshot_vnd,o.net_contribution_snapshot_vnd,coalesce(sum(c.amount_vnd) FILTER(WHERE c.status IN('APPROVED','PAID')),0) commission_cost_vnd,o.net_contribution_snapshot_vnd-coalesce(sum(c.amount_vnd) FILTER(WHERE c.status IN('APPROVED','PAID')),0) net_contribution_after_commission_vnd FROM orders o LEFT JOIN commissions c ON c.order_id=o.id GROUP BY o.id;

ALTER TABLE reservations ENABLE ROW LEVEL SECURITY;ALTER TABLE trade_ins ENABLE ROW LEVEL SECURITY;ALTER TABLE trade_in_inspections ENABLE ROW LEVEL SECURITY;ALTER TABLE trade_in_check_items ENABLE ROW LEVEL SECURITY;ALTER TABLE commissions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON reservations,trade_ins,trade_in_inspections,trade_in_check_items,commissions,order_sales_operations_summary FROM PUBLIC,anon,authenticated;
GRANT ALL ON reservations,trade_ins,trade_in_inspections,trade_in_check_items,commissions TO service_role;GRANT SELECT ON order_sales_operations_summary TO service_role;GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
REVOKE ALL ON FUNCTION next_salesops_code(text,regclass,text),create_trade_in(jsonb,text,text),start_trade_in_inspection(uuid,uuid,text,text,text,text),complete_trade_in_inspection(uuid,text,text,jsonb,text,text),reject_trade_in(uuid,text,text),receive_trade_in(uuid,text,text),expire_reservations(text),create_reservation(bigint,bigint,bigint,timestamptz,bigint,text,uuid,text,text),cancel_reservation(uuid,text,text),extend_reservation(uuid,timestamptz,text,text),convert_reservation_to_order(uuid,bigint,text,text),accept_trade_in(uuid,bigint,numeric,numeric,text),convert_trade_in_to_inventory(uuid,jsonb,text,text),generate_commission(bigint,jsonb,text,text),approve_commission(uuid,text),pay_commission(uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION create_trade_in(jsonb,text,text),start_trade_in_inspection(uuid,uuid,text,text,text,text),complete_trade_in_inspection(uuid,text,text,jsonb,text,text),reject_trade_in(uuid,text,text),receive_trade_in(uuid,text,text),expire_reservations(text),create_reservation(bigint,bigint,bigint,timestamptz,bigint,text,uuid,text,text),cancel_reservation(uuid,text,text),extend_reservation(uuid,timestamptz,text,text),convert_reservation_to_order(uuid,bigint,text,text),accept_trade_in(uuid,bigint,numeric,numeric,text),convert_trade_in_to_inventory(uuid,jsonb,text,text),generate_commission(bigint,jsonb,text,text),approve_commission(uuid,text),pay_commission(uuid,uuid,text,text,text) TO service_role;
COMMIT;
